candidates.raw:
// 1. Input Validation
if (gv_input.enable != 0 && gv_input.enable != 1) {
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s.x = 0.0;
    gv_output.voted_rate_rad_s.y = 0.0;
    gv_output.voted_rate_rad_s.z = 0.0;
    gv_output.distance_rad_s[0] = 0.0;
    gv_output.distance_rad_s[1] = 0.0;
    gv_output.distance_rad_s[2] = 0.0;
    gv_output.outlier_mask = 0U;
    // Do NOT reset state on invalid config, only on disable
    return;
}

for (int i = 0; i < 3; i++) {
    const adcs_vec3_t *g = gv_input.gyro[i];
    if (g == NULL || !adcs_is_finite_vec3(g)) {
        gv_output.mode = GV_FAULT;
        gv_output.voted_rate_rad_s.x = 0.0;
        gv_output.voted_rate_rad_s.y = 0.0;
        gv_output.voted_rate_rad_s.z = 0.0;
        gv_output.distance_rad_s[0] = 0.0;
        gv_output.distance_rad_s[1] = 0.0;
        gv_output.distance_rad_s[2] = 0.0;
        gv_output.outlier_mask = 0U;
        return;
    }
}

double thr = gv_config.threshold_rad_s;
double rthr = gv_config.reentry_threshold_rad_s;
unint32 ic = gv_config.isolate_confirm;
unint32 rc = gv_config.reentry_confirm;

if (!isfinite(thr) || thr < 0.0 ||
    !isfinite(rthr) || rthr < 0.0 || rthr > thr ||
    !isfinite(ic) || ic < 1 || ic > 20 ||
    !isfinite(rc) || rc < 1 || rc > 20) {
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s.x = 0.0;
    gv_output.voted_rate_rad_s.y = 0.0;
    gv_output.voted_rate_rad_s.z = 0.0;
    gv_output.distance_rad_s[0] = 0.0;
    gv_output.distance_rad_s[1] = 0.0;
    gv_output.distance_rad_s[2] = 0.0;
    gv_output.outlier_mask = 0U;
    return;
}

// 2. Disable Handling
if (gv_input.enable == 0) {
    gv_output.mode = GV_OFF;
    gv_output.voted_rate_rad_s.x = 0.0;
    gv_output.voted_rate_rad_s.y = 0.0;
    gv_output.voted_rate_rad_s.z = 0.0;
    gv_output.distance_rad_s[0] = 0.0;
    gv_output.distance_rad_s[1] = 0.0;
    gv_output.distance_rad_s[2] = 0.0;
    gv_output.outlier_mask = 0U;
    for (int i = 0; i < 3; i++) {
        gv_state.isolated[i] = 0;
        gv_state.bad_streak[i] = 0;
        gv_state.good_streak[i] = 0;
    }
    return;
}

// 3. Compute Component-wise Median
adcs_vec3_t median_vec;
double vals[3];

// X component
vals[0] = gv_input.gyro[0]->x;
vals[1] = gv_input.gyro[1]->x;
vals[2] = gv_input.gyro[2]->x;
if (vals[0] > vals[1]) { double t = vals[0]; vals[0] = vals[1]; vals[1] = t; }
if (vals[1] > vals[2]) { double t = vals[1]; vals[1] = vals[2]; vals[2] = t; }
if (vals[0] > vals[1]) { double t = vals[0]; vals[0] = vals[1]; vals[1] = t; }
median_vec.x = vals[1];

// Y component
vals[0] = gv_input.gyro[0]->y;
vals[1] = gv_input.gyro[1]->y;
vals[2] = gv_input.gyro[2]->y;
if (vals[0] > vals[1]) { double t = vals[0]; vals[0] = vals[1]; vals[1] = t; }
if (vals[1] > vals[2]) { double t = vals[1]; vals[1] = vals[2]; vals[2] = t; }
if (vals[0] > vals[1]) { double t = vals[0]; vals[0] = vals[1]; vals[1] = t; }
median_vec.y = vals[1];

// Z component
vals[0] = gv_input.gyro[0]->z;
vals[1] = gv_input.gyro[1]->z;
vals[2] = gv_input.gyro[2]->z;
if (vals[0] > vals[1]) { double t = vals[0]; vals[0] = vals[1]; vals[1] = t; }
if (vals[1] > vals[2]) { double t = vals[1]; vals[1] = vals[2]; vals[2] = t; }
if (vals[0] > vals[1]) { double t = vals[0]; vals[0] = vals[1]; vals[1] = t; }
median_vec.z = vals[1];

// 4. Compute Distances and Outlier Mask
unint32 outlier_mask = 0U;
int outlier_count = 0;
for (int i = 0; i < 3; i++) {
    adcs_vec3_t diff = adcs_vec3_sub(gv_input.gyro[i], &median_vec);
    double dist = adcs_vec3_norm(&diff);
    gv_output.distance_rad_s[i] = dist;

    if (dist > thr) {
        outlier_mask |= (unint32)(1U << i);
        outlier_count++;
    }
}

// 5. Update Isolation State (Streaks)
for (int i = 0; i < 3; i++) {
    int is_outlier = (outlier_mask >> i) & 1U;

    if (!gv_state.isolated[i]) {
        // Not isolated: accumulate bad streak
        if (is_outlier) {
            gv_state.bad_streak[i]++;
            if (gv_state.bad_streak[i] >= gv_config.isolate_confirm) {
                gv_state.isolated[i] = 1;
            }
        } else {
            gv_state.bad_streak[i] = 0;
        }
    } else {
        // Isolated: judge against reentry threshold
        double dist = gv_output.distance_rad_s[i];
        if (dist <= rthr) {
            gv_state.good_streak[i]++;
            if (gv_state.good_streak[i] >= gv_config.reentry_confirm) {
                gv_state.isolated[i] = 0;
                gv_state.bad_streak[i] = 0;
                gv_state.good_streak[i] = 0;
            }
        } else {
            gv_state.good_streak[i] = 0;
        }
    }
}

// 6. Count Isolated Sensors
int isolated_count = 0;
for (int i = 0; i < 3; i++) {
    if (gv_state.isolated[i]) {
        isolated_count++;
    }
}

// 7. Voting Logic
adcs_vec3_t output_rate = {0.0, 0.0, 0.0};
gv_mode_t mode = GV_FAULT;

if (isolated_count == 0) {
    if (outlier_count == 0) {
        mode = GV_NOMINAL;
        output_rate = median_vec;
    } else if (outlier_count == 1) {
        mode = GV_DEGRADED;
        adcs_vec3_t sum = {0.0, 0.0, 0.0};
        int count = 0;
        for (int i = 0; i < 3; i++) {
            if (!((outlier_mask >> i) & 1U)) {
                sum = adcs_vec3_add(&sum, gv_input.gyro[i]);
                count++;
            }
        }
        if (count == 2) {
            output_rate = adcs_vec3_scale(&sum, 0.5);
        }
    }
    // Else: 2 or 3 outliers -> Fault (default)
} else if (isolated_count == 1) {
    int idx1 = -1, idx2 = -1;
    for (int i = 0; i < 3; i++) {
        if (!gv_state.isolated[i]) {
            if (idx1 == -1) idx1 = i;
            else idx2 = i;
        }
    }

    if (idx1 != -1 && idx2 != -1) {
        adcs_vec3_t diff = adcs_vec3_sub(gv_input.gyro[idx1], gv_input.gyro[idx2]);
        double mutual_dist = adcs_vec3_norm(&diff);

        if (mutual_dist <= thr) {
            mode = GV_DEGRADED;
            adcs_vec3_t sum = adcs_vec3_add(gv_input.gyro[idx1], gv_input.gyro[idx2]);
            output_rate = adcs_vec3_scale(&sum, 0.5);
        }
    }
}
// Else: 2 or 3 isolated -> Fault (default)

// 8. Assign Output
gv_output.mode = mode;
gv_output.voted_rate_rad_s = output_rate;

