for (int i = 0; i < 3; ++i) {
    if (gv_input.gyro[i] == NULL || !adcs_is_finite_vec3(gv_input.gyro[i])) {
        inputs_valid = 0;
        break;
    }
}

double threshold = gv_config.threshold_rad_s;
double reentry_threshold = gv_config.reentry_threshold_rad_s;
uint32_t isolate_conf = gv_config.isolate_confirm;
uint32_t reentry_conf = gv_config.reentry_confirm;

int config_valid = 1;
if (!isfinite(threshold) || threshold < 0.0) config_valid = 0;
if (!isfinite(reentry_threshold) || reentry_threshold < 0.0) config_valid = 0;
if (config_valid && reentry_threshold > threshold) config_valid = 0;
if (isolate_conf < 1 || isolate_conf > 20) config_valid = 0;
if (reentry_conf < 1 || reentry_conf > 20) config_valid = 0;

if (gv_input.enable != 1 || !inputs_valid || !config_valid) {
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s.x = 0.0;
    gv_output.voted_rate_rad_s.y = 0.0;
    gv_output.voted_rate_rad_s.z = 0.0;
    gv_output.distance_rad_s[0] = 0.0;
    gv_output.distance_rad_s[1] = 0.0;
    gv_output.distance_rad_s[2] = 0.0;
    gv_output.outlier_mask = 0;

    // Reset state on invalid/disable as per "Disable resets all state"
    // Even if it's an invalid config, we latch FAULT. The prompt says "Disable resets all state".
    // For invalid inputs, it latches FAULT. It doesn't explicitly say reset state for invalid inputs,
    // but usually fault state implies stopping normal operation. 
    // However, strict reading: "Disable resets all state including isolation and streaks."
    // Invalid input just latches FAULT. Does it reset state? 
    // "Fault ... is a separate condition from the streak-based isolation flags."
    // Let's assume we don't reset streaks on invalid input unless it's a disable event, 
    // to preserve isolation status across transient errors if possible, 
    // BUT "Invalid binary enable ... latch FAULT". If enable is invalid (not TRUE32), it acts like disable.
    // If inputs are invalid, it's a runtime error. 
    // To be safe and consistent with "Disable resets", let's only reset if enable is not TRUE32.
    if (gv_input.enable != 1) {
        gv_state.isolated[0] = 0; gv_state.isolated[1] = 0; gv_state.isolated[2] = 0;
        gv_state.bad_streak[0] = 0; gv_state.bad_streak[1] = 0; gv_state.bad_streak[2] = 0;
        gv_state.good_streak[0] = 0; gv_state.good_streak[1] = 0; gv_state.good_streak[2] = 0;
    }
    return;
}

// 2. Component-wise Median Calculation
adcs_vec3_t median = {0};
double vals[3];

// X
vals[0] = gv_input.gyro[0]->x;
vals[1] = gv_input.gyro[1]->x;
vals[2] = gv_input.gyro[2]->x;
if ((vals[0] > vals[1]) && (vals[0] > vals[2])) median.x = (vals[1] > vals[2]) ? vals[1] : vals[2];
else if ((vals[1] > vals[0]) && (vals[1] > vals[2])) median.x = (vals[0] > vals[2]) ? vals[0] : vals[2];
else median.x = (vals[0] > vals[1]) ? vals[1] : vals[0];

// Y
vals[0] = gv_input.gyro[0]->y;
vals[1] = gv_input.gyro[1]->y;
vals[2] = gv_input.gyro[2]->y;
if ((vals[0] > vals[1]) && (vals[0] > vals[2])) median.y = (vals[1] > vals[2]) ? vals[1] : vals[2];
else if ((vals[1] > vals[0]) && (vals[1] > vals[2])) median.y = (vals[0] > vals[2]) ? vals[0] : vals[2];
else median.y = (vals[0] > vals[1]) ? vals[1] : vals[0];

// Z
vals[0] = gv_input.gyro[0]->z;
vals[1] = gv_input.gyro[1]->z;
vals[2] = gv_input.gyro[2]->z;
if ((vals[0] > vals[1]) && (vals[0] > vals[2])) median.z = (vals[1] > vals[2]) ? vals[1] : vals[2];
else if ((vals[1] > vals[0]) && (vals[1] > vals[2])) median.z = (vals[0] > vals[2]) ? vals[0] : vals[2];
else median.z = (vals[0] > vals[1]) ? vals[1] : vals[0];

// 3. Distance Calculation and Outlier Masking
double dists[3];
uint32_t outlier_mask = 0;
for (int i = 0; i < 3; ++i) {
    adcs_vec3_t diff = adcs_vec3_sub(gv_input.gyro[i], &median);
    dists[i] = adcs_vec3_norm(&diff);
    if (dists[i] > threshold) {
        outlier_mask |= (1U << i);
    }
}
gv_output.distance_rad_s[0] = dists[0];
gv_output.distance_rad_s[1] = dists[1];
gv_output.distance_rad_s[2] = dists[2];
gv_output.outlier_mask = outlier_mask;

// 4. Isolation State Updates
int isolated_count = 0;
for (int i = 0; i < 3; ++i) {
    int is_outlier = (outlier_mask & (1U << i)) ? 1 : 0;

    if (gv_state.isolated[i]) {
        // Already isolated
        if (dists[i] <= reentry_threshold) {
            gv_state.good_streak[i]++;
            if (gv_state.good_streak[i] >= reentry_conf) {
                gv_state.isolated[i] = 0;
                gv_state.good_streak[i] = 0;
                gv_state.bad_streak[i] = 0;
            }
        } else {
            gv_state.good_streak[i] = 0;
        }
        isolated_count++;
    } else {
        // Not isolated
        if (is_outlier) {
            gv_state.bad_streak[i]++;
            if (gv_state.bad_streak[i] >= isolate_conf) {
                gv_state.isolated[i] = 1;
                isolated_count++;
            }
        } else {
            gv_state.bad_streak[i] = 0;
        }
    }
}

// 5. Voting Logic
gv_mode_t mode = GV_FAULT;
adcs_vec3_t output_rate = {0, 0, 0};

if (isolated_count == 0) {
    int outlier_cnt = 0;
    for (int i = 0; i < 3; ++i) {
        if (outlier_mask & (1U << i)) outlier_cnt++;
    }

    if (outlier_cnt == 0) {
        mode = GV_NOMINAL;
        output_rate = median;
    } else if (outlier_cnt == 1) {
        mode = GV_DEGRADED;
        adcs_vec3_t sum = {0, 0, 0};
        int count = 0;
        for (int i = 0; i < 3; ++i) {
            if (!(outlier_mask & (1U << i))) {
                sum = adcs_vec3_add(&sum, gv_input.gyro[i]);
                count++;
            }
        }
        output_rate = adcs_vec3_scale(&sum, 1.0 / count);
    } else {
        // 2 or 3 outliers -> Fault, output zero (already initialized)
    }
} else if (isolated_count == 1) {
    int non_iso_indices[2];
    int nni = 0;
    for (int i = 0; i < 3; ++i) {
        if (!gv_state.isolated[i]) {
            non_iso_indices[nni++] = i;
        }
    }

    adcs_vec3_t diff = adcs_vec3_sub(gv_input.gyro[non_iso_indices[0]], gv_input.gyro[non_iso_indices[1]]);
    double mutual_dist = adcs_vec3_norm(&diff);

    if (mutual_dist <= threshold) {
        mode = GV_DEGRADED;
        adcs_vec3_t sum = adcs_vec3_add(gv_input.gyro[non_iso_indices[0]], gv_input.gyro[non_iso_indices[1]]);
        output_rate = adcs_vec3_scale(&sum, 0.5);
    } else {
        // Disagree -> Fault, output zero
    }
} else {
    // 2 or 3 isolated -> Fault, output zero
}

// 6. Final Output Assignment
gv_output.mode = mode;
gv_output.voted_rate_rad_s = output_rate;
